// Identification is the process's job, not the agent's. In the real branch it is
// the photo ID check at the counter. In the demo, tag the message with
// [customer:C1001] to switch customer; C1003 is the default. Both tags are
// removed before the message reaches the guardrail and the agent.
const j = $input.first().json;
const message = j.chatInput ?? j.message ?? '';
const m = message.match(/\[customer:(C\d{4})\]/i);
const customer_id = j.customer_id || (m ? m[1].toUpperCase() : 'C1003');
const c = CUSTOMERS.find(x => x.customer_id === customer_id) || CUSTOMERS[2];
// Tag the run so it can be found in Executions > Filters > Highlighted data.
// A pasted test conversation is matched to its test id; evaluation rows carry one.
// A follow-up such as a confirmation can carry the id explicitly: [test:T06].
const TAGS = /\s*\[(customer:C\d{4}|test:T\d{2})\]/gi;
const norm = s => String(s).replace(TAGS, '').toLowerCase().replace(/\s+/g, ' ').trim();
const t = message.match(/\[test:(T\d{2})\]/i);
const test_id = j.test_id || (t ? t[1].toUpperCase() : '') || (TESTS.find(x => norm(x.message) === norm(message)) || {}).test_id || '';
$execution.customData.set('customer_id', c.customer_id);
if (test_id) $execution.customData.set('test_id', test_id);
return [{ json: {
  test_id,
  chatInput: message.replace(TAGS, '').trim(),
  sessionId: j.sessionId || ('eval-' + (j.test_id ?? j.id ?? Date.now()) + '-' + $execution.id),
  expected_route: j.expected_route || null,
  customer_id: c.customer_id, name: c.name, account_id: c.account_id, balance: c.balance,
  phone: c.phone, email: c.email, open_complaint: c.open_complaint, vulnerability_flag: c.vulnerability_flag,
} }];

