const day = String(query || 'today').toLowerCase();
const hours = { monday: '09:00 to 17:00', tuesday: '09:00 to 17:00', wednesday: '09:00 to 17:00', thursday: '09:00 to 17:00', friday: '09:00 to 17:00', saturday: '09:00 to 13:00', sunday: 'closed' };
const today = ['sunday','monday','tuesday','wednesday','thursday','friday','saturday'][new Date().getDay()];
const key = Object.keys(hours).find(k => day.includes(k)) || today;
return `${key[0].toUpperCase() + key.slice(1)}: ${hours[key]}. Closed on bank holidays.`;

const type = String(query || 'general');
const d = new Date(); d.setDate(d.getDate() + 1);
const fmt = (offset, time) => { const x = new Date(d); x.setDate(x.getDate() + offset); return x.toISOString().slice(0, 10) + ' ' + time; };
return `Next ${type} slots: ${fmt(0, '14:00')}, ${fmt(0, '15:30')}, ${fmt(1, '10:00')}. Each slot is 45 minutes.`;

// The gate reads structured facts, never the model's opinion of itself.
const item = $input.first().json;
const customer = $('Identify customer').first().json;
const request = customer.chatInput || '';

// Refusals from the input guardrail skip the agent entirely.
if (item.route === 'refused') {
  $execution.customData.set('route', 'refused');
  return [{ json: { route: 'refused', classification: 'refused', reply: item.reply, max_risk: 'none', skills_run: [], reasons: ['input guardrail'] } }];
}

const agent = $('AI Agent').first().json;
const reply = item.guardrailsInput || agent.output || '';

// Highest risk of any skill that ran, taken from the skills' own typed results.
const RANK = { none: 0, low: 1, medium: 2, high: 3 };
let max_risk = 'none';
const skills_run = [];
for (const step of agent.intermediateSteps || []) {
  const tool = step.action?.tool;
  let obs = step.observation;
  try { obs = typeof obs === 'string' ? JSON.parse(obs) : obs; } catch (e) {}
  const rows = Array.isArray(obs) ? obs : [obs];
  for (const r of rows) {
    const risk = r?.risk || (r?.json && r.json.risk);
    const status = r?.status || (r?.json && r.json.status);
    if (tool) skills_run.push({ tool, risk: risk || 'n/a', status: status || 'n/a' });
    if (risk && RANK[risk] > RANK[max_risk]) max_risk = risk;
  }
}

// Policy keywords: the decisions the agent must never make.
const KEYWORDS = /\b(loan|lend|lending|borrow|overdraft|credit|mortgage decision|complaint|complain|close my account|close the account|closure|vulnerab)/i;
const reasons = [];
if (RANK[max_risk] >= RANK.medium) reasons.push('skill risk ' + max_risk);
if (customer.open_complaint) reasons.push('open complaint on record');
if (customer.vulnerability_flag) reasons.push('vulnerability flag on record');
if (KEYWORDS.test(request)) reasons.push('policy keyword in request');
if (!reply) reasons.push('empty reply');

// Fail safe: only an explicit, positive classification goes straight through.
const classification = reasons.length === 0 ? 'straight_through' : 'review';
$execution.customData.set('route', classification);
return [{ json: { route: classification, classification, reply, max_risk, skills_run, reasons, customer_id: customer.customer_id } }];

